from itertools import combinations
from pysat.solvers import Glucose3

n = 9
# variables: for each edge (i,j) with i&lt;j, var id = i*n + j + 1 (just need unique positive ints)
# Let's map (i,j) to var id
var_map = {}
counter = 1
for i in range(n):
    for j in range(i+1, n):
        var_map[(i,j)] = counter
        counter += 1

solver = Glucose3()

# Constraint 1: No red K_4. For every 4 vertices, at least one edge is blue (not red).
# If x=1 means red, then clause: at least one x is false (blue)
for quad in combinations(range(n), 4):
    clause = []
    for e in combinations(quad, 2):
        i, j = e
        if i &gt; j:
            i, j = j, i
        clause.append(-var_map[(i,j)])
    solver.add_clause(clause)

# Constraint 2: No blue K_3. For every 3 vertices, at least one edge is red.
# Clause: at least one x is true (red)
for tri in combinations(range(n), 3):
    clause = []
    for e in combinations(tri, 2):
        i, j = e
        if i &gt; j:
            i, j = j, i
        clause.append(var_map[(i,j)])
    solver.add_clause(clause)

print("Number of variables:", counter-1)
print("Number of clauses:", solver.nof_clauses())

sat = solver.solve()
print("SAT:", sat)
if sat:
    model = solver.get_model()
    # Extract values
    vals = {}
    for v in model:
        vals[abs(v)] = 1 if v &gt; 0 else 0
    # Order edges lexicographically
    result = []
    for i in range(n):
        for j in range(i+1, n):
            result.append(vals[var_map[(i,j)]])
    print("Solution:", result)
else:
    print("UNSAT")

