from itertools import combinations
from pysat.solvers import Glucose3

def check_n(n):
    var_map = {}
    counter = 1
    for i in range(n):
        for j in range(i+1, n):
            var_map[(i,j)] = counter
            counter += 1

    solver = Glucose3()

    for quad in combinations(range(n), 4):
        clause = []
        for e in combinations(quad, 2):
            i, j = e
            if i > j:
                i, j = j, i
            clause.append(-var_map[(i,j)])
        solver.add_clause(clause)

    for tri in combinations(range(n), 3):
        clause = []
        for e in combinations(tri, 2):
            i, j = e
            if i > j:
                i, j = j, i
            clause.append(var_map[(i,j)])
        solver.add_clause(clause)

    sat = solver.solve()
    return sat

for n in range(3, 10):
    sat = check_n(n)
    print(f"n={n}: {'SAT' if sat else 'UNSAT'}")
